import sys, io

def apply(path, pairs):
    s = io.open(path, encoding='utf-8').read()
    for i, (o, n) in enumerate(pairs):
        c = s.count(o)
        if c != 1:
            print(f"FAIL {path} pair {i}: {c} matches"); sys.exit(1)
        s = s.replace(o, n)
    io.open(path, 'w', encoding='utf-8').write(s)
    print(f"ok {path}")

